codeExample.bad:
/* Body text at 16px (normal size): #767676 on #FFFFFF is 4.54:1 -- passes AA's 4.5:1 minimum but fails AAA's stricter 7:1 requirement */
.report-summary {
  color: #767676;
  background-color: #FFFFFF;
  font-size: 16px;
  font-weight: normal;
}

codeExample.good:
/* Same 16px text: #454545 on #FFFFFF is 9.59:1 -- comfortably clears the 7:1 minimum required for normal text under AAA */
.report-summary {
  color: #454545;
  background-color: #FFFFFF;
  font-size: 16px;
  font-weight: normal;
}
